import{_ as a,a0 as p,w as s,s as e,I as u,x as n,a1 as o,A as l,ao as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const V=JSON.parse('{"title":"完整指南：使用 VirtualBox 在 Windows 上安装 Ubuntu | LCTT x X-CMD","titleTemplate":false,"description":"完整指南：使用 VirtualBox 在 Windows 上安装 Ubuntu | LCTT (202301) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"完整指南：使用 VirtualBox 在 Windows 上安装 Ubuntu | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"完整指南：使用 VirtualBox 在 Windows 上安装 Ubuntu | LCTT (202301) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202301/20230112.3 ⭐️⭐️ Install Ubuntu on Windows Using VirtualBox [Complete Guide]","title":"完整指南：使用 VirtualBox 在 Windows 上安装 Ubuntu","tag":"202301","desc":""},"relativePath":"202301/20230112.3 ⭐️⭐️ Install Ubuntu on Windows Using VirtualBox [Complete Guide].md","filePath":"[post].md"}'),b={name:"202301/20230112.3 ⭐️⭐️ Install Ubuntu on Windows Using VirtualBox [Complete Guide].md"};function d(w,t,g,m,x,y){const r=p("Link");return s(),e("div",null,[t[29]||(t[29]=u("h1",{id:"完整指南-使用-virtualbox-在-windows-上安装-ubuntu",tabindex:"-1"},[n("完整指南：使用 VirtualBox 在 Windows 上安装 Ubuntu "),u("a",{class:"header-anchor",href:"#完整指南-使用-virtualbox-在-windows-上安装-ubuntu","aria-label":"Permalink to “完整指南：使用 VirtualBox 在 Windows 上安装 Ubuntu”"},"​")],-1)),t[30]||(t[30]=u("p",null,[u("img",{src:"https://img.linux.net.cn/data/attachment/album/202301/23/230204pr8c36xesq5r8vx9.jpg",alt:""})],-1)),t[31]||(t[31]=u("blockquote",null,[u("p",null,"本教程将指导你用最简单的步骤在 Windows 上的 Oracle VirtualBox 上安装 Ubuntu 桌面版。")],-1)),u("p",null,[o(r,{href:"https://www.debugpoint.com/tag/virtualbox"},{default:l(()=>[...t[0]||(t[0]=[n("VirtualBox",-1)])]),_:1}),t[1]||(t[1]=n(" 是 Oracle 的一款流行的虚拟化软件，可用于 Linux、mac 和 Windows 系统。它是灵活的，并提供了许多功能来实现虚拟化。这是在 Windows 中体验 Ubuntu 而不安装它的最佳且简单的方法。然而，我强烈建议将 Ubuntu 以双引导的方式安装在物理机上，从而更好地体验 Ubuntu。",-1))]),t[32]||(t[32]=i('<p>下面列出的步骤假设你是第一次在 Windows 中安装 Ubuntu。因此，这些步骤有点描述性，也有点冗长。此外，以下步骤适用于 Windows 10 和 Windows 11 作为宿主机。</p><h3 id="你需要什么" tabindex="-1">你需要什么 <a class="header-anchor" href="#你需要什么" aria-label="Permalink to “你需要什么”">​</a></h3><ul><li>可上网的 PC</li><li>用于安装的 Ubuntu Linux ISO 镜像文件</li><li>安装了 VirtualBox 的 Windows 系统</li></ul><h3 id="使用-virtualbox-在-windows-上安装-ubuntu" tabindex="-1">使用 VirtualBox 在 Windows 上安装 Ubuntu <a class="header-anchor" href="#使用-virtualbox-在-windows-上安装-ubuntu" aria-label="Permalink to “使用 VirtualBox 在 Windows 上安装 Ubuntu”">​</a></h3><h4 id="下载并安装必要的东西" tabindex="-1">下载并安装必要的东西 <a class="header-anchor" href="#下载并安装必要的东西" aria-label="Permalink to “下载并安装必要的东西”">​</a></h4><p>从以下链接下载 Ubuntu Linux 桌面版 ISO 镜像文件。</p>',6)),u("blockquote",null,[u("p",null,[u("strong",null,[o(r,{href:"https://ubuntu.com/download/desktop"},{default:l(()=>[...t[2]||(t[2]=[n("下载 Ubuntu 桌面版",-1)])]),_:1})])])]),t[33]||(t[33]=u("p",null,"此外，请从下面的官方网站下载 Oracle VirtualBox 安装程序。",-1)),u("blockquote",null,[u("p",null,[u("strong",null,[o(r,{href:"https://www.virtualbox.org/wiki/Downloads"},{default:l(()=>[...t[3]||(t[3]=[n("下载 VirtualBox",-1)])]),_:1})])])]),t[34]||(t[34]=u("p",null,[u("img",{src:"https://www.debugpoint.com/wp-content/uploads/2023/01/Download-location-for-VirtualBox-for-Windows.jpg",alt:"VirtualBox for Windows 的下载位置"})],-1)),t[35]||(t[35]=u("h4",{id:"如何安装和配置-virtualbox",tabindex:"-1"},[n("如何安装和配置 VirtualBox "),u("a",{class:"header-anchor",href:"#如何安装和配置-virtualbox","aria-label":"Permalink to “如何安装和配置 VirtualBox”"},"​")],-1)),t[36]||(t[36]=u("p",null,"Windows 中的 VirtualBox 需要 “Microsoft Visual C++ 2019 Redistrobutiable package”。你必须先安装它。从以下链接下载软件包（X64 架构）：",-1)),u("blockquote",null,[u("p",null,[u("strong",null,[o(r,{href:"https://learn.microsoft.com/en-us/cpp/windows/latest-supported-vc-redist?view=msvc-170"},{default:l(()=>[...t[4]||(t[4]=[n("下载 MSVC",-1)])]),_:1})])])]),t[37]||(t[37]=u("p",null,[u("img",{src:"https://www.debugpoint.com/wp-content/uploads/2023/01/Download-the-dependency-for-VirtualBox.jpg",alt:"下载 VirtualBox 的依赖项"})],-1)),t[38]||(t[38]=u("p",null,[u("img",{src:"https://www.debugpoint.com/wp-content/uploads/2023/01/Install-the-dependency-for-VirtualBox.jpg",alt:"安装 VirtualBox 的依赖项"})],-1)),t[39]||(t[39]=u("p",null,"完成以上安装后，从以下链接下载最新的 Python 包。Python 绑定也是 Windows 端 VirtualBox 安装所需的依赖项。",-1)),u("blockquote",null,[u("p",null,[u("strong",null,[o(r,{href:"https://www.python.org/downloads/windows/"},{default:l(()=>[...t[5]||(t[5]=[n("下载 Python for Windows",-1)])]),_:1})])])]),t[40]||(t[40]=i('<p>然后，启动 VirtualBox 安装程序并按照屏幕上的说明进行安装。</p><p>安装后，重新启动 Windows 系统。</p><h4 id="为-ubuntu-设置虚拟机" tabindex="-1">为 Ubuntu 设置虚拟机 <a class="header-anchor" href="#为-ubuntu-设置虚拟机" aria-label="Permalink to “为 Ubuntu 设置虚拟机”">​</a></h4><p>从开始菜单启动 VirtualBox。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Select-VirtualBox-from-start-menu.jpg" alt="从开始菜单中选择 VirtualBox"></p><p>在 VirtualBox 窗口工具栏上，单击 “<ruby>新建<rt>New</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Click-on-New.jpg" alt="单击新建"></p>',7)),u("ul",null,[t[11]||(t[11]=u("li",null,"在创建虚拟机窗口中，输入虚拟机的名称。它可以是标识此版本 Ubuntu 的任何名称。",-1)),t[12]||(t[12]=u("li",null,[n("保持 “"),u("ruby",null,[n("文件夹"),u("rt",null,"Folder")]),n("” 不变。这是创建虚拟机文件的路径。")],-1)),t[13]||(t[13]=u("li",null,[n("在 “"),u("ruby",null,[n("ISO 镜像文件"),u("rt",null,"ISO Image")]),n("” 一栏，浏览你下载的 Ubuntu ISO 文件。")],-1)),u("li",null,[t[7]||(t[7]=n("然后选择 “",-1)),t[8]||(t[8]=u("ruby",null,[n("跳过无人值守安装"),u("rt",null," Skip Unattended installation")],-1)),t[9]||(t[9]=n("”。如果不选择此选项，将在虚拟机中创建一个 ",-1)),o(r,{href:"https://www.debugpoint.com/virtualbox-id-password/"},{default:l(()=>[...t[6]||(t[6]=[n("默认用户 id（vboxuser）和密码",-1)])]),_:1}),t[10]||(t[10]=n("。让我们暂时不要管它。",-1))])]),t[41]||(t[41]=i('<p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Select-the-ISO-file.jpg" alt="选择 ISO 文件"></p><ul><li>单击 “<ruby>硬件<rt>Hardware</rt></ruby>” 部分，并调整虚拟机所需的内存。一般的经验是，虚拟机的内存大小应该小于主机系统中的物理内存。我建议对于 8 GB 内存系统的虚拟机使用 2 GB 到 4 GB。要选择 4 GB 内存，拖动滑块（或键入）使其为 4096 MB（即 4×1024）。</li><li>选择 2 或 4 核处理器。</li></ul><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Select-Hardware.jpg" alt="选择硬件"></p><ul><li>单击 “<ruby>硬盘<rt>Hard Disk</rt></ruby>” 部分，并保持文件位置不变。</li><li>为 Ubuntu 安装提供至少 20 GB 到 25 GB 的容量。</li><li>硬盘文件类型值保持为 VDI（VirtualBox 磁盘镜像）</li><li>不要选择 “<ruby>预分配完整大小<rt>Pre-allocate Full Size</rt></ruby>”。</li><li>最后，单击 “<ruby>完成<rt>Finish</rt></ruby>”。</li></ul><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Select-Hard-Disk.jpg" alt="选择硬盘"></p><p>你应该在 VirtualBox 的左侧面板上看到一个新条目，其中包含一个 Ubuntu 22.04 条目（你之前设置的名称）。</p><p>选择条目并单击 “<ruby>开始<rt>Start</rt></ruby>” 以引导到虚拟机：</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Boot-Ubuntu-in-VirtualBox.jpg" alt="在 VirtualBox 中启动 Ubuntu"></p><h4 id="使用-virtualbox-安装-ubuntu" tabindex="-1">使用 VirtualBox 安装 Ubuntu <a class="header-anchor" href="#使用-virtualbox-安装-ubuntu" aria-label="Permalink to “使用 VirtualBox 安装 Ubuntu”">​</a></h4><p>成功引导后，你应该看到以下屏幕，其中显示了安装 Ubuntu 的各种选项。选择 “<ruby>尝试 Ubuntu<rt>Try Ubuntu</rt></ruby>” 或 “<ruby>安装 Ubuntu<rt>Install Ubuntu</rt></ruby>”。</p><p>在欢迎屏幕中，单击 “<ruby>尝试 Ubuntu<rt>Try Ubuntu</rt></ruby>”。过了一会儿，你会看到下面的 Ubuntu <ruby>临场<rt>Live</rt></ruby>桌面。如果要更改分辨率，请右键单击桌面并选择显示设置。并将分辨率更改为 1400×900。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/1-Select-Try-Ubuntu.jpg" alt="选择尝试 Ubuntu"></p><p>在桌面上，双击 “<ruby>安装 Ubuntu<rt>Install Ubuntu</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/2-Ubuntu-LIVE-desktop-1.jpg" alt="Ubuntu LIVE 桌面"></p><p>在下一组屏幕中，根据需要选择 “<ruby>语言<rt>Language</rt></ruby>” 和 “<ruby>键盘布局<rt>Keyboard Layout</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Select-Language.jpg" alt="选择语言"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/4-Select-Keybaord-Layout.jpg" alt="选择键盘布局"></p><p>安装屏幕为你提供所需的安装类型。选择 “<ruby>正常安装<rt>Normal Installation</rt></ruby>”，然后在 “<ruby>其他选项<rt>Other options</rt></ruby>” 下选择两个选项。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/5-Select-install-options.jpg" alt="选择安装选项"></p><p>由于你是在虚拟磁盘空间中安装的，即它只是一个文件，因此你可以安全地选择 “<ruby>擦除磁盘并安装 Ubuntu<rt>Erase disk and install Ubuntu</rt></ruby>” 选项。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/6-Installation-Type.jpg" alt="安装类型"></p><p>点击 “<ruby>立即安装<rt>Install Now</rt></ruby>” 并 “<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/7-Write-changes-to-disk.jpg" alt="将更改写入磁盘"></p><p>然后选择 “<ruby>地区<rt>region</rt></ruby>”，添加“<ruby>你的名字<rt>Your name</rt></ruby>”、“<ruby>计算机名称<rt>Your computer&#39;s name</rt></ruby>”、“<ruby>用户名<rt>Username</rt></ruby>” 和 “<ruby>密码<rt>Password</rt></ruby>”。这将是安装后登录 Ubuntu 的用户 id 和密码。</p><p>单击 “<ruby>继续<rt>Continue</rt></ruby>” 开始安装。等到它完成。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/8-User-account-creation.jpg" alt="创建用户帐户"></p><p>安装完成后，单击 “<ruby>立即重新启动<rt>Restart Now</rt></ruby>”。等待几秒钟，你将看到一个登录屏幕。使用用户 id 和密码登录。你应该看到 Ubuntu 桌面在 Windows 端 VirtualBox 中作为 VM 运行。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/10-Ubuntu-Installation-is-complete.jpg" alt="Ubuntu 安装完成"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/11-Log-on-to-Ubuntu.jpg" alt="登录 Ubuntu"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/12-Ubuntu-running-in-Windows-using-Virtualbox-2048x1280.jpg" alt="使用 Virtualbox 在 Windows 中运行的 Ubuntu"></p><h3 id="安装后配置和提示-可选" tabindex="-1">安装后配置和提示（可选） <a class="header-anchor" href="#安装后配置和提示-可选" aria-label="Permalink to “安装后配置和提示（可选）”">​</a></h3><h4 id="安装客体机增强项" tabindex="-1">安装客体机增强项 <a class="header-anchor" href="#安装客体机增强项" aria-label="Permalink to “安装客体机增强项”">​</a></h4><p>成功安装后，应为 Windows 宿主机和 Ubuntu 客体机安装 “<ruby>VirtualBox 客体机增强项<rt>VirtualBox guest additions</rt></ruby>”。客体机增强项是一组需要安装在客体虚拟机（即 Ubuntu）内的软件包，以启用 <strong>共享文件夹、双向复制 / 粘贴、自动更改分辨率</strong> 和许多类似功能。</p><p>要安装它，请引导到 Ubuntu。从 VirtualBox 菜单中，选择“<ruby>设备<rt>Devices</rt></ruby> &gt; <ruby>插入客体机增强 CD 镜像<rt>Insert Guest Additions CD Image</rt></ruby>”。必要的软件包将安装在 Ubuntu 中。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Select-Guest-addition-from-the-menu.jpg" alt="从菜单中选择客体机增强"></p><p>打开文件管理器并打开装入的文件夹，如下所示。然后右键单击 &gt; 选择 “<ruby>在终端中打开<rt>open in terminal</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Open-the-mounted-disc-and-select-option-with-terminal.jpg" alt="打开已挂载的光盘并选择带有终端的选项"></p><p>然后运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ./VBoxLinuxAdditions.run</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/VirtualBox-guest-addition-install-for-Windows-host.jpg" alt="VirtualBox 为 Windows 主机添加客体机增强项"></p><p>完成上述命令后，重新启动 Ubuntu VM。</p><h4 id="启用-windows-和-ubuntu-之间的复制和粘贴" tabindex="-1">启用 Windows 和 Ubuntu 之间的复制和粘贴 <a class="header-anchor" href="#启用-windows-和-ubuntu-之间的复制和粘贴" aria-label="Permalink to “启用 Windows 和 Ubuntu 之间的复制和粘贴”">​</a></h4><p>要在 Windows 和 Ubuntu 系统之间启用复制和粘贴，请从菜单中选择 “<ruby>设备<rt>Devices</rt></ruby> &gt; <ruby>共享剪贴板<rt>Shared Clipboard</rt></ruby> &gt; <ruby>双向<rt>Bi-directional</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Enable-clipboard-sharing.jpg" alt="启用共享剪贴板"></p><h4 id="关闭-ubuntu-vm" tabindex="-1">关闭 Ubuntu VM <a class="header-anchor" href="#关闭-ubuntu-vm" aria-label="Permalink to “关闭 Ubuntu VM”">​</a></h4><p>理想情况下，你应该从自己的关机菜单中关闭 VM。但是，你也可以从 VirtualBox 主窗口关闭。右键单击虚拟机名称并选择 “<ruby>关闭<rt>Close</rt></ruby> &gt; <ruby>关机<rt>Poweroff</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Poweroff-Virtual-machine.jpg" alt="关闭虚拟机"></p><h4 id="如何删除-ubuntu-并删除所有数据" tabindex="-1">如何删除 Ubuntu 并删除所有数据 <a class="header-anchor" href="#如何删除-ubuntu-并删除所有数据" aria-label="Permalink to “如何删除 Ubuntu 并删除所有数据”">​</a></h4><p>如果要完全删除虚拟机（例如 Ubuntu）及其数据，请选择 “<ruby>删除<rt>Remove</rt></ruby>” 和 “<ruby>删除所有文件<rt>Delete All Files</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Select-remove-to-delete-a-VM.jpg" alt="选择删除以移除虚拟机"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Select-the-delete-options.jpg" alt="选择删除选项"></p><h3 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to “结语”">​</a></h3><p>在本教程中，你学习了使用 VirtualBox 在 Windows（10 或 11）上安装 Ubuntu 的最简单方法。此外，你还学习了几步安装后配置 Ubuntu VM 的基本步骤。你可以对 VirtualBox 中的其他任何 Linux 发行版使用上述步骤。</p><p>如果你有任何疑问，欢迎在下面发表评论。</p><hr>',55)),u("p",null,[t[15]||(t[15]=n("via: ",-1)),o(r,{href:"https://www.debugpoint.com/install-ubuntu-windows-virtualbox/"},{default:l(()=>[...t[14]||(t[14]=[n("https://www.debugpoint.com/install-ubuntu-windows-virtualbox/",-1)])]),_:1})]),u("p",null,[t[20]||(t[20]=n("作者：",-1)),o(r,{href:"https://www.debugpoint.com/author/admin1/"},{default:l(()=>[...t[16]||(t[16]=[n("Arindam",-1)])]),_:1}),t[21]||(t[21]=n(" 选题：",-1)),o(r,{href:"https://github.com/lkxed"},{default:l(()=>[...t[17]||(t[17]=[n("lkxed",-1)])]),_:1}),t[22]||(t[22]=n(" 译者：",-1)),o(r,{href:"https://github.com/ZhangZhanhaoxiang"},{default:l(()=>[...t[18]||(t[18]=[n("ZhangZhanhaoxiang",-1)])]),_:1}),t[23]||(t[23]=n(" 校对：",-1)),o(r,{href:"https://github.com/wxy"},{default:l(()=>[...t[19]||(t[19]=[n("wxy",-1)])]),_:1})]),u("p",null,[t[26]||(t[26]=n("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[24]||(t[24]=[n("LCTT",-1)])]),_:1}),t[27]||(t[27]=n(" 原创编译，",-1)),o(r,{href:"https://linux.cn/"},{default:l(()=>[...t[25]||(t[25]=[n("Linux中国",-1)])]),_:1}),t[28]||(t[28]=n(" 荣誉推出",-1))])])}const f=a(b,[["render",d]]);export{V as __pageData,f as default};
